const steps = [
  { id: "you", name: "You", title: "About you", fields: [
    { name: "name", label: "Full name", validate: "required", autoComplete: "name" },
    { name: "email", label: "Email", type: "email", validate: "email" },
  ] },
  { id: "plan", name: "Plan", title: "Pick a plan", fields: [
    { name: "plan", label: "Plan", type: "choice", required: true, options: plans.map((p) => ({ value: p.id, title: p.name, meta: p.price })) },
  ] },
  { id: "review", name: "Review", title: "Check everything", review: true },
];
const [busy, setBusy] = useState(false);
const [error, setError] = useState("");
const [done, setDone] = useState(false);

<MultiStepForm
  steps={steps}
  submitLabel="Create account"
  loading={busy}
  submitError={error}
  complete={done}
  completeTitle={(v) => `Welcome, ${v.name}`}
  onSubmit={async (values) => {
    setBusy(true); setError("");
    try { await api.signup(values); setDone(true); } catch (e) { setError(e.message); } finally { setBusy(false); }
  }}
/>
